export const INITIAL_CARRIERS: Carrier[] = RAW_INITIAL_CARRIERS.map((carrier): Carrier => {
  if (carrier.mode === 'WCA' || Boolean(carrier.wcaId)) {
    return {
      ...carrier,
      altaEntity: 'Performer',
    };
  }
  return carrier;
});
